import type { TranslationBlock } from './types'

const blocks: TranslationBlock[] = [
{ type: 'heading', zh: '中山经', en: 'Classic of the Central Mountains' },
    { type: 'para', zh: '《中山经》薄山之首，曰甘枣之山。共水出焉，而西流注于河。其上多杻木，其下有草焉，葵本而杏叶，黄华而荚实，名曰籜，可以已瞢。有兽焉，其状如𤠢鼠而文题，其名曰㔮，食之已瘿。', en: 'The Central Mountains begin at Mount Ganzao, head of the Thin Mountains. The Gong River flows west into the Yellow River. It has many oak trees above and a grass below called tui, with sunflower stems, apricot leaves, yellow flowers and pod fruit—it cures blindness. A beast called the nao, shaped like a rat with a patterned forehead—eating it cures goiter.' },
    { type: 'para', zh: '又东二十里，曰历儿之山，其上多橿，多櫔木，是木也，方茎而员叶，黄华而毛，其实如揀，服之不忘。', en: 'Twenty li east is Mount Li\'er, with many zhen trees and li trees—these have square stems, round leaves, yellow flowers and bristles, with fruit like dates; eating it prevents forgetfulness.' },
    { type: 'para', zh: '又东十五里，曰渠猪之山，其上多竹，渠猪之水出焉，而南流注于河。其中是多豪鱼，状如鲔，而赤喙赤尾赤羽，可以已白癣。', en: 'Fifteen li east is Mount Quzhu, with much bamboo. The Quzhu River flows south into the Yellow River. It contains many hao fish, shaped like wei fish with red beaks, red tails and red feathers—they cure white ringworm.' },
    { type: 'para', zh: '又东三十五里，曰葱聋之山，其中多大谷，是多白垩，黑、青、黄垩。', en: 'Thirty-five li east is Mount Conglong, with many large valleys, much white chalk, and black, blue and yellow chalk.' },
    { type: 'para', zh: '又东十五里，曰涹山，其上多赤铜，其阴多铁。', en: 'Fifteen li east is Mount Wo, with much red copper above and iron on its north face.' },
    { type: 'para', zh: '又东七十里，曰脱扈之山。有草焉，其状如葵叶而红华，荚实，实如棕椶荚，名曰植楮，可以已癙，食之不眯。', en: 'Seventy li east is Mount Tuohu. A grass called zhichu, shaped like sunflower leaves with red flowers and pod fruit like brown palm pods—it cures melancholy and eating it prevents nightmares.' },
    { type: 'para', zh: '又东二十里，曰金星之山，多天婴，其状如龙骨，可以已痤。', en: 'Twenty li east is Mount Jinxing, with much tianying that looks like dragon bones—it cures acne.' },
    { type: 'para', zh: '又东七十里，曰泰威之山，其中有谷，曰枭谷，其中多铁。', en: 'Seventy li east is Mount Taiwei, with a valley called Xiao Gu containing much iron.' },
    { type: 'para', zh: '又东十五里，曰橿谷之山，其中多赤铜。', en: 'Fifteen li east is Mount Zhengu, with much red copper.' },
    { type: 'para', zh: '又东百二十里，曰吴林之山，其中多茝草。', en: 'One hundred twenty li east is Mount Wulin, with much jian grass.' },
    { type: 'para', zh: '又北三十里，曰牛首之山。有草焉，名曰鬼草，其叶如葵而赤茎，其秀如禾，服之不忧。劳水出焉，而西流注于潏水。是多飞鱼，其状如鲋鱼，食之已痔衕。', en: 'Thirty li north is Mount Niushou. A grass called guicao, with sunflower-like leaves and red stems, flowering like grain—eating it prevents worry. The Lao River flows west into the Yu waters, containing many flying fish shaped like crucian carp—eating them cures hemorrhoids and fistula.' },
    { type: 'para', zh: '又北四十里，曰霍山，其木多榖。有兽焉，其状如狸，而白尾有鬛，名曰朏朏，养之可以已忧。', en: 'Forty li north is Mount Huo, with much paper mulberry. A beast called the feifei, shaped like a badger with a white tail and mane—raising it relieves sorrow.' },
    { type: 'para', zh: '又北五十二里，曰合谷之山，是多薝棘。', en: 'Fifty-two li north is Mount Hegu, with much zhan thorn.' },
    { type: 'para', zh: '又北三十五里，曰阴山，多砺石、文石。少水出焉，其中多彫棠，其叶如榆叶而方，其实如赤菽，食之已聋。', en: 'Thirty-five li north is Mount Yin, with much whetstone and patterned stone. The Shao River flows from it, containing many diao tang trees with elm-like square leaves and red bean-like fruit—eating them cures deafness.' },
    { type: 'para', zh: '又东北四百里，曰鼓鐙之山，多赤铜。有草焉，名曰荣草，其叶如柳，其本如鸡卵，食之已风。', en: 'Four hundred li northeast is Mount Gudeng, with much red copper. A grass called rongcao, with willow-like leaves and roots like chicken eggs—it cures wind disorders.' },
    { type: 'para', zh: '凡薄山之首，自甘枣之山至于鼓鐙之山，凡十五山，六千六百七十里。历儿、冢也，其祠礼：毛，太牢之具；县婴以吉玉。其余十三者，毛用一羊，县婴用藻珪，瘗而不糈。藻珪者，藻玉也，方其下而锐其上，而中穿之加金。', en: 'In all, the Thin Mountains from Mount Ganzao to Mount Gudeng comprise fifteen peaks spanning 6,670 li. Li\'er is the tomb—for its sacrifice, the full set of livestock is used and the infant is suspended with auspicious jade. The remaining thirteen use a ram, with the infant suspended using an algae gui, buried without grain. The algae gui is algae jade—square at the bottom, pointed at the top, pierced in the middle and inlaid with gold.' },
    { type: 'heading', zh: '中次二经', en: 'Central Mountains II' },
    { type: 'para', zh: '《中次二经》济山之首，曰煇诸之山，其上多桑，其兽多闾麋，其鸟多鶡。', en: 'The second Central Mountains, the Ji Mountains, begin at Mount Huizhu, with much mulberry, white deer as beasts, and he birds as birds.' },
    { type: 'para', zh: '又西南二百里，曰发视之山，其上多金玉，其下多砥砺。即鱼之水出焉，而西流注于伊水。', en: 'Two hundred li southwest is Mount Fashi, with gold and jade above and whetstones and grindstones below. The Jiyu River flows west into the Yi River.' },
    { type: 'para', zh: '又西三百里，曰豪山，其上多金玉而无草木。', en: 'Three hundred li west is Mount Hao, with gold and jade but no plants.' },
    { type: 'para', zh: '又西三百里，曰鲜山，多金玉，无草木。鲜水出焉，而北流注于伊水。其中多鸣蛇，其状如蛇而四翼，其音如磬，见则其邑大旱。', en: 'Three hundred li west is Mount Xian, with gold and jade but no plants. The Xian River flows north into the Yi River, containing many ming snakes—serpents with four wings and a sound like a chime stone; their appearance brings great drought.' },
    { type: 'para', zh: '又西三百里，曰阳山，多石，无草木。阳水出焉，而北流注于伊水。其中多化蛇，其状如人面而豺身，鸟翼而蛇行，其音如叱呼，见则其邑大水。', en: 'Three hundred li west is Mount Yang, with much stone and no plants. The Yang River flows north into the Yi River, containing many hua snakes—human-faced, jackal-bodied, with bird wings and serpentine movement, whose cry is like shouting; their appearance brings great floods.' },
    { type: 'para', zh: '又西二百里，曰昆吾之山，其上多赤铜。有兽焉，其状如彘而有角，其音如号，名曰蠪蛭，食之不眯。', en: 'Two hundred li west is Mount Kunwu, with much red copper above. A beast called the longzhi, shaped like a pig with horns and a voice like wailing—eating it prevents nightmares.' },
    { type: 'para', zh: '又西百二十里，曰里，曰葌山，葌水出焉，而北流注于伊水，其上多金玉，其下多青雄黄。有木焉，其状如棠而赤叶，名曰芒草，可以毒鱼。', en: 'One hundred twenty li west is Mount Jian. The Jian River flows north into the Yi River, with gold and jade above and blue realgar below. A tree called mangcao, shaped like a tang tree with red leaves—it can poison fish.' },
    { type: 'para', zh: '又西一百五十里，曰独苏之山，无草木而多水。', en: 'One hundred fifty li west is Mount Dusu, with no plants and much water.' },
    { type: 'para', zh: '又西一百二十里，曰蔓渠之山，其上多金玉，其下多竹箭。伊水出焉，而东流注于洛。有兽焉，其名曰马腹，其状如人面虎身，其音如婴儿，是食人。', en: 'One hundred twenty li west is Mount Manqu, with gold and jade above and bamboo arrows below. The Yi River flows east into the Luo River. A beast called the mafu, with a human face and tiger body, has a voice like a baby\'s and devours people.' },
    { type: 'para', zh: '凡济山之首，自煇诸之山至于蔓渠之山，凡九山，一千六百七十里。其神皆人面而鸟身。祠用毛，用一吉玉，投而不糈。', en: 'In all, the Ji Mountains from Mount Huizhu to Mount Manqu comprise nine peaks spanning 1,670 li. Their spirits all have human faces and bird bodies. For the sacrifice, fur is used with one beautiful jade, cast without grain.' },
    { type: 'heading', zh: '中次三经', en: 'Central Mountains III' },
    { type: 'para', zh: '《中次三经》萯山之首，曰敖岸之山，其阳多㻬琈之玉，其阴多赭、黄金。神熏池居之。是常出美玉。北望河林，其状如莤如举。有兽焉，其状如白鹿而四角，名曰夫诸，见则其邑大水。', en: 'The third Central Mountains, the Tai Mountains, begin at Mount Ao\'an, with turou jade on its south face and ochre and gold on its north. The god Xunchi dwells here, and fine jade often emerges from it. To the north, the river forest looks like xi or ju. A beast called the fuzhu, shaped like a white deer with four horns—its appearance brings great floods.' },
    { type: 'para', zh: '又东十里，曰青要之山，实惟帝之密都。是多驾鸟。南望墠渚，禹父之所化，是多仆累、蒲卢。䰠武罗司之，其状人面而豹文，小要而白齿，而穿耳以鐻，其鸣如鸣玉。是山也，宜女子。畛水出焉，而北流注于河。其中有鸟焉，名曰鴢，其状如凫，青身而朱目赤尾，食之宜子。有草焉，其状如葌，而方茎黄华赤实，其本如藁本，名曰荀草，服之美人色。', en: 'Ten li east is Mount Qingyao, truly the Emperor\'s secret capital. There are many jia birds. To the south lies Tiantan, where Yu\'s father was transformed, with many puli and pulu. The deity Wuluo manages it—human-faced with leopard markings, a narrow waist and white teeth, with ears pierced by jade rings, whose voice is like ringing jade. This mountain benefits women. The Zhen River flows north into the Yellow River. A bird called the you, shaped like a duck with a blue body, red eyes and red tail—eating it promotes childbearing. A grass called xuncao, shaped like jian grass with square stems, yellow flowers and red fruit, with roots like gaoben—eating it beautifies complexion.' },
    { type: 'para', zh: '又东十里曰騩山，其上有美枣，其阴有㻬琈之玉。正回之水出焉，而北流注于河。其中多飞鱼，其状如豚而红文，服之不畏雷，可以御兵。', en: 'Ten li east is Mount Gui, with fine jade above and turou jade below. The Zhenghui River flows north into the Yellow River, containing many flying fish shaped like pigs with red patterns—wearing them dispels fear of thunder and wards off weapons.' },
    { type: 'para', zh: '又东四十里，曰宜苏之山，其上多金玉，其下多蔓居之木。滽滽之水出焉，而北流注于河，是多黄贝。', en: 'Forty li east is Mount Yisu, with gold and jade above and many manju trees below. The Yongyong River flows north into the Yellow River, containing many yellow shells.' },
    { type: 'para', zh: '又东二十里，曰和山，其上无草木而多瑶碧，实惟河之九都。是山也五曲，九水出焉，合而北流注于河，其中多苍玉。吉神泰逢司之，其状如人而虎尾，是好居于萯山之阳，出入有光。泰逢神动天地气也。', en: 'Twenty li east is Mount He, with no plants but much jasper, truly the nine capitals of the Yellow River. This mountain has five bends; nine rivers flow from it, joining and flowing north into the Yellow River, containing much blue jade. The auspicious god Taifeng manages it—human-faced with a tiger tail, dwelling on the south face of the Tai Mountains, emerging and entering with light. The Taifeng spirit moves the qi of heaven and earth.' },
    { type: 'para', zh: '凡萯山之首，自敖岸之山至于和山，凡五山，四百四十里。其祠：泰逢、熏池、武罗皆一牡羊副，婴用吉玉。其二神用一雄鸡瘗之，糈用稌。', en: 'In all, the Tai Mountains from Mount Ao\'an to Mount He comprise five peaks spanning 440 li. For the sacrifice: Taifeng, Xunchi and Wuluo each use a split ram, with the infant using auspicious jade. The two other gods use one rooster buried, with millet for grain.' },
    { type: 'heading', zh: '中次四经', en: 'Central Mountains IV' },
    { type: 'para', zh: '《中次四经》釐山之首，曰鹿蹄之山，其上多玉，其下多金。甘水出焉，而北流注于洛，其中多泠石。', en: 'The fourth Central Mountains, the Xi Mountains, begin at Mount Luti, with jade above and gold below. The Gan River flows north into the Luo River, containing much ling stone.' },
    { type: 'para', zh: '西五十里，曰扶猪之山，其上多礝石。有兽焉，其状如貉而人目，其名曰䴦。虢水出焉，而北流注于洛，其中多瓀石。', en: 'Fifty li west is Mount Fuzhu, with much ruan stone. A beast called the ying, shaped like a raccoon dog with human eyes. The Guo River flows north into the Luo River, containing much ruan stone.' },
    { type: 'para', zh: '又西一百二十里，曰釐山，其阳多玉，其阴多蒐。有兽焉，其状如牛。苍身，其音如婴儿，是食人，其名曰犀渠。滽滽之水出焉，而南流注于伊水。有兽焉，名曰𤢺，其状如獳犬而有鳞，其毛如彘鬣。', en: 'One hundred twenty li west is Mount Xi, with jade on its south face and sou on its north. A beast called the xiqu, shaped like an ox with a blue body and a voice like a baby\'s, devours people. The Yongyong River flows south into the Yi River. A beast called the xiao, shaped like a scaly dog with bristles like a wild boar\'s mane.' },
    { type: 'para', zh: '又西二百里，曰箕尾之山，多榖，多涂石，其上多㻬琈之玉。', en: 'Two hundred li west is Mount Jiwei, with much paper mulberry, tu stone, and turou jade above.' },
    { type: 'para', zh: '又西二百五十里，曰柄山，其上多玉，其下多铜。滔雕之水出焉，而北流注于洛。其中多羬羊。有木焉，其状如樗，其叶如桐而荚实，其名曰茇，可以毒鱼。', en: 'Two hundred fifty li west is Mount Bing, with jade above and copper below. The Taodiao River flows north into the Luo River, containing many qian sheep. A tree called ba, shaped like a chinaberry with paulownia-like leaves and pod fruit—it can poison fish.' },
    { type: 'para', zh: '又西二百里，曰白边之山，其上多金玉，其下多青雄黄。', en: 'Two hundred li west is Mount Baibian, with gold and jade above and blue realgar below.' },
    { type: 'para', zh: '又西二百里，曰熊耳之山，其上多漆，其下多椶。浮濠之水出焉，而西流注于洛，其中多水玉，多人鱼。有草焉，其状如蘓而红华，名曰葶薴，可以毒鱼。', en: 'Two hundred li west is Mount Xiong\'er, with lacquer above and palm below. The Fuhao River flows west into the Luo River, containing much water jade and many human fish. A grass called tingning, shaped like perilla with red flowers—it can poison fish.' },
    { type: 'para', zh: '又西三百里，曰牡山，其上多文石，其下多竹箭竹䉋，其兽多兽多㸲牛、羬羊，鸟多赤鷩。', en: 'Three hundred li west is Mount Mu, with much patterned stone above and bamboo arrows below, zong cattle and qian sheep as beasts, and red pheasants as birds.' },
    { type: 'para', zh: '又西三百五十里，曰讙举之山。雒水出焉，而东北流注于玄扈之水，其中多马肠之物。此二山者，洛閒也。', en: 'Three hundred fifty li west is Mount Huanju. The Luo River flows northeast into the Xuanyou waters, containing much machang creatures. These two mountains lie between the Luo.' },
    { type: 'para', zh: '凡釐山之首，自鹿蹄之山至于玄扈之山，凡九山，千六百七十里。其神状皆人面兽身。其祠之，毛用一白鸡，祈而不糈，以采衣之。', en: 'In all, the Xi Mountains from Mount Luti to Mount Xuanyou comprise nine peaks spanning 1,670 li. Their spirits all have human faces and beast bodies. For the sacrifice, a white rooster is used for prayer without grain, dressed in colorful garments.' },
    { type: 'heading', zh: '中次五经', en: 'Central Mountains V' },
    { type: 'para', zh: '《中次五经》薄山之首，曰苟牀之山，无草木，多怪石。', en: 'The fifth Central Mountains, the Thin Mountains, begin at Mount Gouchuang, with no plants and many strange stones.' },
    { type: 'para', zh: '东三百里，曰首山，其阴多榖柞，其草多𦬸芫，其阳多㻬琈之玉，木多槐。其阴有谷，曰机谷，多䲦鸟，其状如枭而三目，有耳，其音如录，食之已垫。', en: 'Three hundred li east is Mount Shou, with paper mulberry and oak on its north face, much xuan yuan grass, turou jade on its south face and many scholar trees. A valley on its north face called Ji Gu has many dai birds, shaped like owls with three eyes and ears, whose cry is like lu—eating them cures depression.' },
    { type: 'para', zh: '又东三百里，曰县劚之山，无草木，多文石。', en: 'Three hundred li east is Mount Xianchu, with no plants and much patterned stone.' },
    { type: 'para', zh: '又东三百里，曰葱聋之山，无草木，多𢈪石。', en: 'Three hundred li east is Mount Conglong, with no plants and much zhang stone.' },
    { type: 'para', zh: '东北五百里，曰条谷之山，其木多槐桐，其草多芍药、虋冬。', en: 'Five hundred li northeast is Mount Tiaogu, with many scholar trees and paulownia, much peony and men dong grass.' },
    { type: 'para', zh: '又北十里，曰超山，其阴多苍玉，其阳有井，冬有水而夏竭。', en: 'Ten li north is Mount Chao, with much blue jade on its north face and a well on its south that has water in winter and dries in summer.' },
    { type: 'para', zh: '又东五百里，曰成侯之山，其上多櫄木，其草多芃。', en: 'Five hundred li east is Mount Chenghou, with much chun trees above and much peng grass.' },
    { type: 'para', zh: '又东五百里，曰朝歌之山，谷多美垩。', en: 'Five hundred li east is Mount Chaoge, with much fine chalk in its valley.' },
    { type: 'para', zh: '又东五百里，曰槐山，谷多金锡。', en: 'Five hundred li east is Mount Huai, with much gold and tin in its valley.' },
    { type: 'para', zh: '又东十里，曰历山，其木多槐，其阳多玉。', en: 'Ten li east is Mount Li, with many scholar trees and jade on its south face.' },
    { type: 'para', zh: '又东十里，曰尸山，多苍玉，其兽多麖。尸水出焉，南流注于洛水，其中多美玉。', en: 'Ten li east is Mount Shi, with much blue jade and many mi deer. The Shi River flows south into the Luo waters, containing much beautiful jade.' },
    { type: 'para', zh: '又东十里，曰良馀之山，其上多榖柞，无石。馀水出于其阴，而北流注于河；乳水出于其阳，而东南流注于洛。', en: 'Ten li east is Mount Liangyu, with much paper mulberry and oak above and no stones. The Yu River flows from its north face into the Yellow River; the Ru River flows from its south face southeast into the Luo.' },
    { type: 'para', zh: '又东南十里，曰蛊尾之山，多砺石、赤铜。龙馀之水出焉，而东南流注于洛。', en: 'Ten li southeast is Mount Guwei, with much whetstone and red copper. The Longyu River flows southeast into the Luo.' },
    { type: 'para', zh: '又东北二十里，曰升山，其木其多榖柞棘，其草多藇蕙，多寇脱。黄酸之水出焉，而北流注于河，其中多璇玉。', en: 'Twenty li northeast is Mount Sheng, with much paper mulberry, oak and thorns, much yu hui grass and koutuo. The Huang Suan River flows north into the Yellow River, containing much xuan jade.' },
    { type: 'para', zh: '又东二十里，曰阳虚之山，多金，临于玄扈之水。', en: 'Twenty li east is Mount Yangxu, with much gold, overlooking the Xuanyou waters.' },
    { type: 'para', zh: '凡薄山之首，自苟林之山至于阳虚之山，凡十六山，二千九百八十二里。升山，冢也，其祠礼：太牢，婴用吉玉。首山，䰠也，其祠用稌、黑牺、太牢之具、糱酿；干儛，置鼓；婴用一璧。尸水，合天也，肥牲祠之，用一黑犬于上，用一雌鸡于下，刉一牝羊，献血。婴用吉玉，采之，飨之。', en: 'In all, the Thin Mountains from Mount Goulin to Mount Yangxu comprise sixteen peaks spanning 2,982 li. Sheng is the tomb—for its sacrifice, the full set of livestock is used with the infant in auspicious jade. Shou is the deity—its sacrifice uses millet, black livestock, the full set of vessels and fermented liquor; dancing with drums; one bi for the Infant. Shui water joins heaven—a fat sacrificial animal is used, with a black dog above and a hen below, cutting a ewe to offer blood. The Infant uses auspicious jade with colorful garments, and offerings are made.' },
    { type: 'heading', zh: '中次六经', en: 'Central Mountains VI' },
    { type: 'para', zh: '《中次六经》縞羝山之首，曰平逢之山，南望伊洛，东望穀城之山，无草木，无水，多沙石。有神焉，其状如人而二首，名曰骄虫，是为螫虫，实惟蜂蜜之庐，其祠之：用一雄鸡，穰而勿杀。', en: 'The sixth Central Mountains, the Gaodi Mountains, begin at Mount Pingfeng, overlooking the Yi and Luo to the south and the Gucheng Mountains to the east, with no plants, no water and much sand and stone. A deity called the jiaochong, shaped like a human with two heads, is the stinging insect—the dwelling place of bees. For its sacrifice, a rooster is used for blessing without killing.' },
    { type: 'para', zh: '西十里，曰縞羝之山，无草木，多金玉。', en: 'Ten li west is Mount Gaodi, with no plants and much gold and jade.' },
    { type: 'para', zh: '又西十里，曰廆山，其阴多㻬琈之玉。其阴有谷，名曰雚谷，其木多柳楮。其中有鸟焉，状如山鸡而长尾，赤如丹火而青喙，名曰鴒䳩，其鸣自呼，服之不眯。交觞之水出于其阳，而南流注于洛；俞随之水出于其阴，而北流注于穀水。', en: 'Ten li west is Mount Wei, with much turou jade on its north face. A valley called Huangu on its north face has many willows and paper mulberries. A bird called the lingyan, shaped like a pheasant with a long tail, red like cinnabar fire with a blue beak, has a cry like its name—eating it prevents nightmares. The Jiaoshang River flows from its south face into the Luo; the Yusui River flows from its north face into the Gu waters.' },
    { type: 'para', zh: '又西三十里，曰瞻诸之山，其阳多金，㴬水出焉，而东南流注于洛；少水出于其阴，而东流注于穀水。', en: 'Thirty li west is Mount Zhu Zhu, with much gold on its south face. The Xie River flows southeast into the Luo; the Shao River flows from its north face east into the Gu waters.' },
    { type: 'para', zh: '又西三十里，曰娄涿之山，无草木，多金玉。瞻水出于其阳，而东流注于洛；陂水出于其阴，而北流注于穀水，其中多茈石、文石。', en: 'Thirty li west is Mount Louzhuo, with no plants and much gold and jade. The Zhan River flows from its south face east into the Luo; the Bei River flows from its north face into the Gu waters, containing many purple and patterned stones.' },
    { type: 'para', zh: '又西四十里，曰白石之山。惠水出于其阳，而南流注于洛，其中多水玉。涧水出于其阴，西北流注于穀水，其中多麋石、櫨丹。', en: 'Forty li west is Mount Baishi. The Hui River flows from its south face into the Luo, containing much water jade. The Jian River flows from its north face northwest into the Gu waters, containing much mi stone and ludan.' },
    { type: 'para', zh: '又西五十里，曰榖山，其上多榖，其下多桑。爽水出焉，而西北流注于榖水，其中多碧绿。', en: 'Fifty li west is Mount Gu, with much paper mulberry above and mulberry below. The Shuang River flows northwest into the Gu waters, containing much blue green.' },
    { type: 'para', zh: '又西七十二里，曰密山，其阳多玉，其阴多铁。豪水出焉，而南流注于洛，其中多旋龟，其状鸟首而鼈尾，其音如判木。无草木。', en: 'Seventy-two li west is Mount Mi, with jade on its south face and iron on its north. The Hao River flows south into the Luo, containing many xuan turtles with bird heads and turtle tails, whose cry is like splitting wood. No plants.' },
    { type: 'para', zh: '又西百里，曰长石之山，无草木，多玉。其西有谷焉，名曰共谷，多竹。共水出焉，西南流注于洛，其中多鸣石。', en: 'One hundred li west is Mount Changshi, with no plants and much jade. A valley called Gonggu to its west has much bamboo. The Gong River flows southwest into the Luo, containing much ming stone.' },
    { type: 'para', zh: '又西一百四十里，曰傅山，无草木，多瑶碧。厌染之水出于其阳，而南流注于洛，其中多人鱼。其西有林焉，名曰墦冢。穀水出焉，而东流注于洛，其中多㻒玉。', en: 'One hundred forty li west is Mount Fu, with no plants and much jasper. The Yanran River flows from its south face into the Luo, containing many human fish. A forest called Fanzhong lies to its west. The Gu River flows east into the Luo, containing much xuan jade.' },
    { type: 'para', zh: '又西五十里，曰橐山，其木多樗，多𣖾木，其阳多金玉，其阴多铁，多萧。橐水出焉，而北流注于河。其中多脩辟之鱼，状如黾而白喙，其音如鸱，食之已白癣。', en: 'Fifty li west is Mount Tuo, with many chinaberry and zhi trees, gold and jade on its south face, iron and much xiao on its north. The Tuo River flows north into the Yellow River, containing many xiupi fish shaped like frogs with white beaks, whose cry is like an owl\'s—eating them cures white ringworm.' },
    { type: 'para', zh: '又西九十里，曰常烝之山，无草木，多垩。潐水出焉，而东北流注于河，其中多苍玉。菑水出焉，而北流注于河。', en: 'Ninety li west is Mount Changzheng, with no plants and much chalk. The Jiao River flows northeast into the Yellow River, containing much blue jade. The Zi River flows north into the Yellow River.' },
    { type: 'para', zh: '又西九十里，曰夸父之山，其木多椶枏、多竹箭，其兽多㸲牛、羬羊，其鸟多鷩，其阳多玉，其阴多铁。其北有林焉，名曰桃林，是广员三百里，其中多马。湖水出焉，而北流注于河，其中多㻒玉。', en: 'Ninety li west is Mount Kuafu, with much palm and nanmu and bamboo arrows, zong cattle and qian sheep as beasts, pheasants as birds, jade on its south face and iron on its north. A forest called Taolin to its north is three hundred li square, with much horses. The Hu River flows north into the Yellow River, containing much xuan jade.' },
    { type: 'para', zh: '又西九十里，曰阳华之山，其阳多金玉，其阴多青雄黄，其草多藷藇，多苦辛，其状如橚，其实如瓜，其味酸甘，食之已疟。杨水出焉，而西南流注于洛，其中多人鱼。门水出焉，而东北流注于河，其中多玄䃤。𦁎姑之水出于其阴，而东流注于门水，其上多铜。门水出于河，七百九十里入雒水。', en: 'Ninety li west is Mount Yanghua, with gold and jade on its south face, blue realgar on its north, much shuyu and bitter xin grass shaped like xu, with melon-like fruit tasting sour-sweet—eating it cures malaria. The Yang River flows southwest into the Luo, containing many human fish. The Men River flows northeast into the Yellow River, containing much black stone. The Qigu River flows from its north face into the Men waters, with much copper above. The Men River flows from the Yellow River, 790 li into the Luo.' },
    { type: 'para', zh: '凡縞羝山之首，自平逢之山至于阳华之山，凡十四山，七百九十里。嶽在其中，以六月祭之，如诸嶽之祠法，则天下安宁。', en: 'In all, the Gaodi Mountains from Mount Pingfeng to Mount Yanghua comprise fourteen peaks spanning 790 li. The sacred mountain is among them, sacrificed to in the sixth month following the rites of the sacred mountains—then the world is at peace.' },
    { type: 'heading', zh: '中次七经', en: 'Central Mountains VII' },
    { type: 'para', zh: '《中次七经》苦山之首，曰休舆之山。其上有石焉，名曰帝台之棋，五色而文，其状如鹑卵，帝台之石，所以祷百神者也，服之不蛊。有草焉，其状如蓍，红叶而本丛生，名曰夙条，可以为簳。', en: 'The seventh Central Mountains, the Bitter Mountains, begin at Mount Xiuyu. A stone called the Emperor Tai\'s chess lies above—five-colored with patterns, like quail eggs. The Emperor Tai\'s stone is used to pray to all gods; eating it prevents poison. A grass called sutiao, shaped like shi grass with red leaves and clustered roots, can be used for arrow shafts.' },
    { type: 'para', zh: '东三百里，曰鼓钟之山，帝台之所以觞百神也。有草焉，方茎而黄华，员叶而三成，其名曰焉酸，可以为毒。其上多砺，其下多砥。', en: 'Three hundred li east is Mount Guzhong, where the Emperor Tai feasts all gods. A grass called yansuan, with square stems, yellow flowers and round leaves in threes, can be used as poison. There are many whetstones above and grindstones below.' },
    { type: 'para', zh: '又东二百里，曰姑媱之山。帝女死焉，其名曰女尸，化为䔄草，其叶胥成，其华黄，其实如菟丘，服之媚于人。', en: 'Two hundred li east is Mount Guyao. The Emperor\'s daughter died here, called Nüshi, and transformed into yaocao—its leaves grow in clusters, its flowers are yellow, and its fruit is like tuqiu; eating it makes one charming to others.' },
    { type: 'para', zh: '又东二十里，曰苦山。有兽焉，名曰山膏，其状如逐，赤若丹火，善詈。其上有木焉，名曰黄棘，黄华而员叶，其实如兰。服之不字。有草焉，员叶而无茎，赤华而不实，名曰无条，服之不瘿。', en: 'Twenty li east is Mount Ku. A beast called the shangao, shaped like a zhu and red as cinnabar fire, is good at cursing. A tree called huangji above has yellow flowers and round leaves, with fruit like orchid—eating it prevents pregnancy. A grass called wutiao, with round leaves and no stems, red flowers and no fruit—eating it prevents goiter.' },
    { type: 'para', zh: '又东二十七里，曰堵山，神天愚居之，是多怪风雨。其上有木焉，名曰天楄，方茎而葵状，服之不㖶。', en: 'Twenty-seven li east is Mount Du, where the god Tianyu dwells, with much strange wind and rain. A tree called tianbian above, with square stems and sunflower-like shape—eating it prevents choking.' },
    { type: 'para', zh: '又东五十二里，曰放皋之山。明水出焉。南流注于伊水，其中多苍玉。有木焉，其叶如槐，黄华而不实，其名曰蒙木，服之不惑。有兽焉，其状如蜂，枝尾而反舌，善呼，其名曰文文。', en: 'Fifty-two li east is Mount Fanggao. The Ming River flows south into the Yi waters, containing much blue jade. A tree called mengmu, with scholar-tree leaves, yellow flowers and no fruit—eating it prevents confusion. A beast called wenwen, shaped like a bee with a branched tail and reversed tongue, is good at calling.' },
    { type: 'para', zh: '又东五十七里，曰大𩇵之山，多㻬琈之玉，多麋玉。有草焉，其状叶如榆，方茎而苍伤，其名曰牛伤，其根苍文，服者不厥，可以御兵。其阳狂水出焉，西南流注于伊水，其中多三足龟，食者无大疾，可以已肿。', en: 'Fifty-seven li east is Mount Dayou, with much turou jade and mi jade. A grass called niushang, with elm-like leaves, square stems and blue wounds, has blue-patterned roots—eating it prevents fainting and wards off weapons. The Kuang River flows from its south face southwest into the Yi waters, containing many three-legged turtles—eating them prevents major illness and cures swelling.' },
    { type: 'para', zh: '又东七十里，曰半石之山，其上有草焉，生而秀，其高丈馀，赤叶黄华，华而不实，其名曰嘉荣，服之者不霆。来需之水出于其阳，而西流注于伊水，其中多鯩鱼，黑文，其状如鲋，食者不睡。合水出于其阴，而北流注于洛，多鰧鱼，状如鳜，居逵，苍文赤尾，食者不痈，可以为瘻。', en: 'Seventy li east is Mount Banshi. A grass called jiarong grows and flowers there, over a zhang tall, with red leaves and yellow flowers, blooming without fruit—eating it prevents thunder. The Laixu River flows from its south face west into the Yi waters, containing many lun fish with black patterns, shaped like crucian carp—eating them prevents sleep. The He River flows from its north face into the Luo, containing many tang fish shaped like mandarin fish, dwelling in culverts, with blue patterns and red tails—eating them prevents abscesses and cures fistula.' },
    { type: 'para', zh: '又东五十里，曰少室之山，百草木成囷。其上有木焉，其名曰帝休，叶状如杨，其枝五衢，黄华黑实，服者不怒。其上多玉，其下多铁。休水出焉，而北流注于洛，其中多䱱鱼，状如𥂕蜼而长距，足白而对，食者无蛊疾，可以御兵。', en: 'Fifty li east is Mount Shaoshi, with all plants and trees forming granaries. A tree called dixiu above has poplar-like leaves, five branches, yellow flowers and black fruit—eating it prevents anger. There is much jade above and iron below. The Xiu River flows north into the Luo, containing many ti fish shaped like flying lemurs with long spurs, with white feet in pairs—eating them prevents poison and wards off weapons.' },
    { type: 'para', zh: '又东三十里，曰泰室之山。其上有木焉，叶状如梨而赤理，其名曰栯木，服者不妒。有草焉，其状如𦬸，白华黑实，泽如蘡薁，名曰䔄草，服之不眯。上多美石。', en: 'Thirty li east is Mount Taishi. A tree called yumu above has pear-like leaves with red grain—eating it prevents jealousy. A grass called yaocao, shaped like xuan, with white flowers and black fruit, glossy like yingyu grapes—eating it prevents nightmares. There is much fine stone above.' },
    { type: 'para', zh: '又北三十里，曰讲山，其上多玉，多柘，多柏。有木焉，名曰帝屋，叶状如椒，反伤赤实，可以御凶。', en: 'Thirty li north is Mount Jiang, with much jade, hackberry and cypress. A tree called diwu, with pepper-like leaves, reversed thorns and red fruit—it wards off evil.' },
    { type: 'para', zh: '又北三十里，曰婴梁之山，上多苍玉，錞于玄石。', en: 'Thirty li north is Mount Yingliang, with much blue jade above, standing over black stone.' },
    { type: 'para', zh: '又东三十里，曰浮戏之山。有木焉，叶状如樗而赤实，名曰亢木，食之不蛊，汜水出焉，而北流注于河。其东有谷，因名曰蛇谷，上多少辛。', en: 'Thirty li east is Mount Fuxi. A tree called kangmu, with chinaberry-like leaves and red fruit—eating it prevents poison. The Si River flows north into the Yellow River. A valley to its east is called Snake Valley, with much du xin.' },
    { type: 'para', zh: '又东四十里，曰少陉之山。有草焉，名曰𦱌草，叶状如葵，而赤茎白花，实如蘡薁，食之不愚。器难之水出焉，而北流注于役水。', en: 'Forty li east is Mount Shaoxing. A grass called jiancao, with sunflower-like leaves, red stems, white flowers and fruit like yingyu grapes—eating it prevents foolishness. The Qinan River flows north into the Yi waters.' },
    { type: 'para', zh: '又东南十里，曰太山。有草焉，名曰棃，其叶状如荻而赤华，可以已疽。太水出于其阳，而东南注于役水；承水出于其阴，而东北流注于役。', en: 'Ten li southeast is Mount Tai. A grass called li, shaped like miscanthus with red flowers—it cures abscesses. The Tai River flows from its south face southeast into the Yi waters; the Cheng River flows from its north face northeast into the Yi.' },
    { type: 'para', zh: '又东二十里，曰末山，上多赤金。末水出焉，北流注于役。', en: 'Twenty li east is Mount Mo, with much red gold above. The Mo River flows north into the Yi.' },
    { type: 'para', zh: '又东二十五里，曰役山，上多白金，多铁。役水出焉，北流注于河。', en: 'Twenty-five li east is Mount Yi, with much white gold and iron. The Yi River flows north into the Yellow River.' },
    { type: 'para', zh: '又东三十五里，曰敏山。上有木焉，其状如荆，白华而赤实，名曰葪柏，服之不寒。其阳多㻬琈之玉。', en: 'Thirty-five li east is Mount Min. A tree called jibai above, shaped like vitex with white flowers and red fruit—eating it prevents cold. There is much turou jade on its south face.' },
    { type: 'para', zh: '又东三十里，曰大騩之山，其阴多铁、美玉、青垩。有草焉，其状如蓍而毛，青华而白实，其名曰𦵧，服之不夭，可以为腹病。', en: 'Thirty li east is Mount Dagui, with iron, fine jade and blue chalk on its north face. A grass called yao, shaped like shi grass with bristles, blue flowers and white fruit—eating it prevents early death and cures abdominal disease.' },
    { type: 'para', zh: '凡苦山之首，自休舆之山至于大騩之山，凡十有九山，千一百八十四里。其十六神者，皆豕身而人面。其祠：毛牷用一羊羞，婴用一藻玉瘗。苦山、少室、太室皆冢也，其祠之：太牢之具，婴以吉玉。其神状皆人面而三首。其余属皆豕身人面也。', en: 'In all, the Bitter Mountains from Mount Xiuyu to Mount Dagui comprise nineteen peaks spanning 1,184 li. Their sixteen spirits all have pig bodies and human faces. For the sacrifice, a pure ram is used for the offering, with one algae jade buried for the infant. Ku, Shaoshi and Taishi are all tombs—for their sacrifice, the full set of livestock is used with the infant in auspicious jade. Their spirits have human faces with three heads. The rest are all pig-bodied with human faces.' },
    { type: 'heading', zh: '中次八经', en: 'Central Mountains VIII' },
    { type: 'para', zh: '《中次八经》荆山之首，曰景山，其上多金玉，其木多杼、檀。雎水出焉，东南流注于江，其中多丹粟，多文鱼。', en: 'The eighth Central Mountains, the Jing Mountains, begin at Mount Jing, with gold and jade above and catalpa and sandalwood trees. The Ju River flows southeast into the Yangtze, containing much cinnabar and many patterned fish.' },
    { type: 'para', zh: '东北百里，曰荆山，其阴多铁，其阳多赤金，其中多牦牛，多豹虎，其木多松柏，其草多竹，多橘櫾。漳水出焉，而东南流注于雎，其中多黄金，多鲛鱼，其兽多闾麋。', en: 'One hundred li northeast is Mount Jing, with iron on its north face, red copper on its south, many yaks, leopards and tigers, pines and cypresses, much bamboo, oranges and pomelos. The Zhang River flows southeast into the Ju, containing much gold, many sharks, and many white deer.' },
    { type: 'para', zh: '又东北百五十里，曰骄山，其上多玉，其下多青雘，其木多松柏，多桃枝钩端。神𧕛围处之，其状如人面。羊角虎爪，恒游于雎漳之渊，出入有光。', en: 'One hundred fifty li northeast is Mount Jiao, with jade above and azurite below, pines and cypresses and many peach branches with hooked tips. The deity Weiwei dwells here—human-faced with ram horns and tiger claws, constantly swimming in the depths of Ju and Zhang, emerging and entering with light.' },
    { type: 'para', zh: '又东北百二十里，曰女几之山，其上多玉，其下多黄金，其兽多豹虎，多闾麋麖麂，其鸟多白鷮，多翟，多鸩。', en: 'One hundred twenty li northeast is Mount Nüji, with jade above and gold below, tigers, leopards, white deer, mi and muntjac as beasts, and white pheasants, pheasants and poisonous birds.' },
    { type: 'para', zh: '又东北二百里，曰宜诸之山，其上多金玉，其下多青雘。洈水出焉，而南流注于漳，其中多白玉。', en: 'Two hundred li northeast is Mount Yizhu, with gold and jade above and azurite below. The Wei River flows south into the Zhang, containing much white jade.' },
    { type: 'para', zh: '又东北三百五十里，曰纶山，其木多梓枏，多桃枝，多柤粟橘櫾，其兽多闾麈麢㚟。', en: 'Three hundred fifty li northeast is Mount Lun, with catalpa and nanmu, many peach branches, jujubes, oranges and pomelos, and white deer, antelopes and xiao as beasts.' },
    { type: 'para', zh: '又东二百里，曰陆䣀之山，其上多㻬琈之玉，其下多垩，其木多杻橿。', en: 'Two hundred li east is Mount Lu\'ang, with turou jade above, chalk below, and oak and zhen trees.' },
    { type: 'para', zh: '又东百三十里，曰光山，其上多碧，其下多木。神计蒙处之，其状人身而龙首，恒游于漳渊，出入必有飘风暴雨。', en: 'One hundred thirty li east is Mount Guang, with much jasper above and many trees below. The deity Jimeng dwells here—human-bodied with a dragon head, constantly swimming in the Zhang depths, with wind and rain when emerging or entering.' },
    { type: 'para', zh: '又东百五十里，曰岐山，其阳多赤金，其阴多白瑉，其上多金玉，其下多青雘，其林多樗。神涉𧕛处之，其状人身而方面三足。', en: 'One hundred fifty li east is Mount Qi, with red copper on its south face, white silver on its north, gold and jade above, azurite below, and many chinaberry trees in its forest. The deity Shewei dwells here—human-bodied with a square face and three feet.' },
    { type: 'para', zh: '又东百三十里，曰铜山，其上多金银铁，其木多榖柞柤栗橘櫾，其兽多犳。', en: 'One hundred thirty li east is Mount Tong, with gold, silver and iron above, and paper mulberry, oak, jujube, orange and pomelos, with many tao beasts.' },
    { type: 'para', zh: '又东北一百里，曰美山，其兽多兕牛，多闾麈，多豕鹿，其上多金，其下多青雘。', en: 'One hundred li northeast is Mount Mei, with rhinoceros cattle, white deer, pigs and deer as beasts, gold above and azurite below.' },
    { type: 'para', zh: '又东北百里，曰大尧之山，其木多松柏，多梓桑，多机，其草多竹，其兽多豹虎麢㚟。', en: 'One hundred li northeast is Mount Dayao, with pines and cypresses, catalpa and mulberry, ji trees, much bamboo, and tigers, leopards, antelopes and xiao as beasts.' },
    { type: 'para', zh: '又东北三百里，曰灵山，其上多金玉，其下多青雘，其木多桃李梅杏。', en: 'Three hundred li northeast is Mount Ling, with gold and jade above, azurite below, and peach, plum, apricot and cherry trees.' },
    { type: 'para', zh: '又东北七十里，曰龙山，上多寓木，其上多碧，其下多赤锡，其草多桃枝钩端。', en: 'Seventy li northeast is Mount Long, with many yu trees, jasper above, red tin below, and many peach branches with hooked tips.' },
    { type: 'para', zh: '又东南五十里，曰衡山，上多寓木榖柞，多黄垩白垩。', en: 'Fifty li southeast is Mount Heng, with yu trees, paper mulberry and oaks, and much yellow and white chalk.' },
    { type: 'para', zh: '又东南七十里，曰石山，其上多金，其下多青雘，多寓木。', en: 'Seventy li southeast is Mount Shi, with gold above, azurite below and many yu trees.' },
    { type: 'para', zh: '又南百二十里，曰若山，其上多㻬琈玉，多赭，多邽石，多寓木，多柘。', en: 'One hundred twenty li south is Mount Ruo, with turou jade, ochre, gui stones, yu trees and hackberry trees.' },
    { type: 'para', zh: '又东南一百二十里，曰彘山，多美石，多柘。', en: 'One hundred twenty li southeast is Mount Zhi, with much beautiful stone and many hackberry trees.' },
    { type: 'para', zh: '又东南一百五十里，曰玉山，其上多金玉，其下多碧、铁，其木多柏。', en: 'One hundred fifty li southeast is Mount Yu, with gold and jade above, jasper and iron below, and many cypress trees.' },
    { type: 'para', zh: '又东南七十里，曰讙山，其木多檀，多封石，多白锡。郁水出于其上，潜于其下，其中多砥砺。', en: 'Seventy li southeast is Mount Huan, with sandalwood trees, feng stone and white tin. The Yu River flows above and below, containing many whetstones and grindstones.' },
    { type: 'para', zh: '又东北百五十里，曰仁举之山，其木多榖柞，其阳多赤金，其阴多赭。', en: 'One hundred fifty li northeast is Mount Renju, with paper mulberry and oaks, red copper on its south face and ochre on its north.' },
    { type: 'para', zh: '又东五十里，曰师每之山，其阳多砥砺，其阴多青雘，其木多柏，多檀，多柘，其草多竹。', en: 'Fifty li east is Mount Shimei, with whetstones and grindstones on its south face, azurite on its north, and cypress, sandalwood and hackberry trees with much bamboo.' },
    { type: 'para', zh: '又东南二百里，曰琴鼓之山，其木多榖柞椒柘，其上多白瑉，其下多洗石，其兽多豕鹿，多白犀，其鸟多鸩。', en: 'Two hundred li southeast is Mount Qingu, with paper mulberry, oak, pepper and hackberry trees, white silver above, wash stones below, pigs, deer and white rhinos as beasts, and poisonous birds as birds.' },
    { type: 'para', zh: '凡荆山之首，自景山至琴鼓之山，凡二十三山，二千八百九十里。其神状皆鸟身而人面。其祠：用一雄鸡祈瘗，用一藻圭，糈用稌。骄山，冢也，其祠：用羞酒少牢祈瘗，婴毛一璧。', en: 'In all, the Jing Mountains from Mount Jing to Mount Qingu comprise twenty-three peaks spanning 2,890 li. Their spirits all have bird bodies and human faces. For the sacrifice: a rooster is used for prayer and burial, one algae gui, with millet for grain. Jiao Mountain is the tomb—its sacrifice uses wine, the full set of livestock for prayer and burial, with infant fur and one bi.' },
    { type: 'heading', zh: '中次九经', en: 'Central Mountains IX' },
    { type: 'para', zh: '《中次九经》岷山之首，曰女几之山，其上多石涅，其木多杻橿，其草多菊𦬸。洛水出焉，东注于江，其中多雄黄，其兽多虎豹。', en: 'The ninth Central Mountains, the Min Mountains, begin at Mount Nüji, with much graphite above, oak and zhen trees, and chuan xuan grass. The Luo River flows east into the Yangtze, containing much realgar, with tigers and leopards as beasts.' },
    { type: 'para', zh: '又东北三百里，曰岷山。江水出焉，东北流注于海，其中多良龟，多鼍，其上多金玉，其下多白瑉，其木多梅棠，其兽多犀象，多夔牛，其鸟多翰鷩。', en: 'Three hundred li northeast is Mount Min. The Yangtze River flows northeast into the sea, containing many fine turtles, alligators, gold and jade above, white silver below, plum and tang trees, rhinoceros, elephants and kui cattle as beasts, and han and pheasant birds.' },
    { type: 'para', zh: '又东北一百四十里，曰崃山，江水出焉，东流注于江。其阳多黄金，其阴多麋麈，其木多檀柘，其草多䪥韭，多葯、空夺。', en: 'One hundred forty li northeast is Mount Lai. The Yangtze River flows east into the Yangtze, with much gold on its south face, elk and deer on its north, sandalwood and hackberry trees, much chive grass, and medicines and kongduo.' },
    { type: 'para', zh: '又东一百五十里，曰崌山。江水出焉，东流注于大江，其中多怪蛇，多䲀鱼，其木多楢杻，多梅梓，其兽多夔牛麢㚟犀兕。有鸟焉，状如鸮而赤身白首，其名曰窃脂，可以御火。', en: 'One hundred fifty li east is Mount Ju. The Yangtze River flows east into the great Yangtze, containing many strange snakes, chi fish, yu and oak trees, plum and catalpa trees, kui cattle, antelopes, xiao, rhinoceros and buffalo as beasts. A bird called the qiezhi, shaped like an owl with a red body and white head, wards off fire.' },
    { type: 'para', zh: '又东三百里，曰高梁之山，其上多垩，其下多砥砺，其木多桃枝钩端。有草焉，状如葵而赤华、荚实、白柎，可以走马。', en: 'Three hundred li east is Mount Gaoliang, with chalk above, whetstones and grindstones below, and peach branches with hooked tips. A grass shaped like sunflowers with red flowers, pod fruit and white calyx can make horses run.' },
    { type: 'para', zh: '又东四百里，曰蛇山，其上多黄金，其下多垩，其木多栒，多橡章，其草多嘉荣、少辛。有兽焉，其状如狐，而白尾长耳，名𤜣狼，见则国内有兵。', en: 'Four hundred li east is Mount She, with gold above, chalk below, xun and zhang trees, jiarong and shaoxin grass. A beast called the lang, shaped like a fox with a white tail and long ears, foretells war within the country.' },
    { type: 'para', zh: '又东五百里，曰鬲山，其阳多金，其阴多白珉。蒲𪈘之水出焉，而东流注于江，其中多白玉，其兽多犀象熊罴，多猿蜼。', en: 'Five hundred li east is Mount Ge, with gold on its south face and white silver on its north. The Pumai River flows east into the Yangtze, containing much white jade, rhinoceros, elephants, bears and raccoon dogs as beasts, and many apes and monkeys.' },
    { type: 'para', zh: '又东北三百里，曰隅阳之山，其上多金玉，其下多青雘，其木多梓桑，其草多茈。徐之水出焉，东流注于江，其中多丹粟。', en: 'Three hundred li northeast is Mount Yuyang, with gold and jade above, azurite below, catalpa and mulberry trees, and much purple chive grass. The Xu River flows east into the Yangtze, containing much cinnabar.' },
    { type: 'para', zh: '又东二百五十里，曰岐山，其上多白金，其下多铁。其木多梅梓，多杻楢。减水出焉，东南流注于江。', en: 'Two hundred fifty li east is Mount Qi, with white gold above and iron below, plum and catalpa trees, and oak and yu trees. The Jian River flows southeast into the Yangtze.' },
    { type: 'para', zh: '又东三百里，曰勾檷之山，其上多玉，其下多黄金，其木多栎柘，其草多芍药。', en: 'Three hundred li east is Mount Goumi, with jade above, gold below, oak and hackberry trees, and much peony.' },
    { type: 'para', zh: '又东一百五十里，曰风雨之山，其上多白金，其下多石涅；其木多棷椫，多杨。宣余之水出焉，东流注于江，其中多蛇。其兽多闾麋，多麈豹虎，其鸟多白鷮。', en: 'One hundred fifty li east is Mount Fengyu, with white gold above and graphite below, zhu and shan trees and poplars. The Xuanyu River flows east into the Yangtze, containing many snakes. Its beasts include white deer, deer, leopards and tigers; its birds include white pheasants.' },
    { type: 'para', zh: '又东北二百里，曰玉山，其阳多铜，其阴多赤金，其木多豫章楢杻，其兽多豕鹿麢㚟，其鸟多鸩。', en: 'Two hundred li northeast is Mount Yu, with copper on its south face, red gold on its north, zhang, yu and oak trees, pigs, deer, antelopes and xiao as beasts, and poisonous birds.' },
    { type: 'para', zh: '又东一百五十里，曰熊山。有穴焉，熊之穴，恒出神人。夏启而冬闭；是穴也，冬启乃必有兵。其上多白玉，其下多白金，其林多樗柳，其草多寇脱。', en: 'One hundred fifty li east is Mount Xiong. A cave called the Bear\'s Cave constantly emits divine people. It opens in summer and closes in winter; if this cave opens in winter, there will certainly be war. It has white jade above, white gold below, chinaberry and willow trees, and much koutuo grass.' },
    { type: 'para', zh: '又东一百四十里，曰騩山，其阳多美玉赤金，其阴多铁，其木多桃枝荆棘。', en: 'One hundred forty li east is Mount Gui, with fine jade and red gold on its south face, iron on its north, and peach branches, thorns and brambles.' },
    { type: 'para', zh: '又东二百里，曰葛山，其上多赤金，其下多瑊石，其木多柤栗橘櫾楢杻，其兽多麢㚟，其草多嘉荣。', en: 'Two hundred li east is Mount Ge, with red gold above, jie stone below, jujube, orange, pomelo, yu and oak trees, antelopes and xiao as beasts, and much jiarong grass.' },
    { type: 'para', zh: '又东一百七十里，曰贾超之山，其阳多黄垩，其阴多美赭，其木多柤栗橘櫾，其中多龙脩。', en: 'One hundred seventy li east is Mount Jiachao, with yellow chalk on its south face, fine ochre on its north, jujube, orange and pomelo trees, and much longxiu inside.' },
    { type: 'para', zh: '凡岷山之首，自女几山至于贾超之山，凡十六山，三千五百里。其神状皆马身而龙首。其祠：毛用一雄鸡瘗。糈用稌。文山、勾檷、风雨、騩之山，是皆冢也，其祠之：羞酒，少牢具，婴毛一吉玉。熊山，帝也，其祠：羞酒，太牢具，婴用一璧。干儛，用兵以禳；祈，璆冕舞。', en: 'In all, the Min Mountains from Mount Nüji to Mount Jiachao comprise sixteen peaks spanning 3,500 li. Their spirits all have horse bodies and dragon heads. For the sacrifice: one rooster is buried, with millet for grain. Wenshan, Goumi, Fengyu and Gui are all tombs—their sacrifice uses wine, the full set of livestock, with infant fur and one auspicious jade. Xiong Mountain is the emperor—its sacrifice uses wine, the full set of livestock, with one bi for the infant. Dancing with weapons dispels evil; prayer is made with qiu and mian dancing.' },
    { type: 'heading', zh: '中次十经', en: 'Central Mountains X' },
    { type: 'para', zh: '《中次十经》之首，曰首阳之山，其上多金玉，无草木。', en: 'The tenth Central Mountains begin at Mount Shouyang, with gold and jade and no plants.' },
    { type: 'para', zh: '又西五十里，曰虎尾之山，其木多椒椐，多封石；其阳多赤金，其阴多铁。', en: 'Fifty li west is Mount Huwei, with pepper and zhen trees, feng stone, red copper on its south face and iron on its north.' },
    { type: 'para', zh: '又西南五十里，曰繁繢之山，其木多楢杻，其草多枝勾。', en: 'Fifty li southwest is Mount Fanhui, with yu and oak trees, and much branch-and-hook grass.' },
    { type: 'para', zh: '又西南二十里，曰勇石之山，无草木，多白金，多水。', en: 'Twenty li southwest is Mount Yongshi, with no plants, much white gold and much water.' },
    { type: 'para', zh: '又西二十里，曰复州之山，其木多檀，其阳多黄金。有鸟焉，其状如鸮，而一足彘尾，其名曰跂踵，见则其国大疫。', en: 'Twenty li west is Mount Fuzhou, with sandalwood trees and gold on its south face. A bird called the qizhong, shaped like an owl with one foot and a pig\'s tail, foretells great plagues.' },
    { type: 'para', zh: '又西三十里，曰楮山，多寓木，多椒椐，多柘，多垩。', en: 'Thirty li west is Mount Chu, with yu trees, pepper and zhen trees, hackberry trees and much chalk.' },
    { type: 'para', zh: '又西二十里，曰又原之山，其阳多青雘，其阴多铁，其鸟多鸜鹆。', en: 'Twenty li west is Mount Youyuan, with azurite on its south face, iron on its north, and many myna birds.' },
    { type: 'para', zh: '又西五十里，曰涿山，其木多榖柞杻，其阳多㻬琈之玉。', en: 'Fifty li west is Mount Zhuo, with paper mulberry, oak and oak trees, and turou jade on its south face.' },
    { type: 'para', zh: '又西七十里，曰丙山，其木多梓檀，多弞杻。', en: 'Seventy li west is Mount Bing, with catalpa and sandalwood trees and many shen oak trees.' },
    { type: 'para', zh: '凡首阳山之首，自首山至于丙山，凡九山，二百六十七里。其神状皆龙身而人面。其祠之：毛用一雄鸡瘗，糈用五种之糈。堵山，冢也，其祠之：少牢具，羞酒祠，婴毛一璧瘗。騩山，帝也，其祠：羞酒，太牢其；合巫祝二人儛，婴一璧。', en: 'In all, the tenth Central Mountains from Mount Shouyang to Mount Bing comprise nine peaks spanning 267 li. Their spirits all have dragon bodies and human faces. For the sacrifice: one rooster is buried, with five types of grain. Du Mountain is the tomb—its sacrifice uses the full set of livestock, wine, with infant fur and one bi buried. Gui Mountain is the emperor—its sacrifice uses wine, the full set of livestock, two shamans dancing, with one bi for the infant.' },
    { type: 'heading', zh: '中次十一经', en: 'Central Mountains XI' },
    { type: 'para', zh: '《中次十一经》荆山之首，曰翼望之山。湍水出焉，东流注于济；贶水出焉，东南流注于汉，其中多蛟。其上多松柏，其下多漆梓，其阳多赤金，其阴多珉。', en: 'The eleventh Central Mountains, the Jing Mountains, begin at Mount Yiwang. The Tuan River flows east into the Ji River; the Kuang River flows southeast into the Han River, containing many flood dragons. There are pines and cypresses above, lacquer and catalpa trees below, red copper on its south face and silver on its north.' },
    { type: 'para', zh: '又东北一百五十里，曰朝歌之山。潕水出焉，东南流注于荥，其中多人鱼。其上多梓枏，其兽多麢麋。有草焉，名曰莽草，可以毒鱼。', en: 'One hundred fifty li northeast is Mount Chaoge. The Wu River flows southeast into the Xing waters, containing many human fish. There are catalpa and nanmu trees above, antelopes and deer as beasts, and a grass called mangcao that can poison fish.' },
    { type: 'para', zh: '又东南二百里，曰帝囷之山，其阳多㻬琈之玉，其阴多铁。帝囷之水出于其上，潜于其下，多鸣蛇。', en: 'Two hundred li southeast is Mount Diqun, with turou jade on its south face and iron on its north. The Diqun River flows above and below, with many ming snakes.' },
    { type: 'para', zh: '又东南五十里，曰视山，其上多韭。有井焉，名曰天井，夏有水，冬竭。其上多桑，多美垩金玉。', en: 'Fifty li southeast is Mount Shi, with much chive above. A well called Tianjing has water in summer and dries in winter. There is much mulberry above, and much fine chalk, gold and jade.' },
    { type: 'para', zh: '又东南二百里，曰前山，其木多槠，多柏，其阳多金，其阴多赭。', en: 'Two hundred li southeast is Mount Qian, with zhu and cypress trees, gold on its south face and ochre on its north.' },
    { type: 'para', zh: '又东南三百里，曰丰山。有兽焉，其状如猿，赤目，赤喙、黄身，名曰雍和，见则国有大恐。神耕父处之，常游清泠之渊，出入有光，见则其国为败。有九锺焉，是知霜鸣。其上多金，其下多榖柞杻橿。', en: 'Three hundred li southeast is Mount Feng. A beast called the yonghe, shaped like an ape with red eyes, red beak and yellow body, brings great fear to the nation. The deity Gengfu dwells here, constantly swimming in the Qingling depths, emerging and entering with light—his appearance foretells national ruin. There are nine bells that ring with the frost. There is much gold above and paper mulberry, oak and oak trees below.' },
    { type: 'para', zh: '又东北八百里，曰兔牀之山，其阳多铁，其木多藷芧，其草多鸡谷，其本如鸡卵，其味酸甘，食者利于人。', en: 'Eight hundred li northeast is Mount Tuchuang, with iron on its south face, shuyu trees, chicken-grain grass with roots like chicken eggs, tasting sour-sweet—eating it benefits people.' },
    { type: 'para', zh: '又东六十里，曰皮山，多垩，多赭，其木多松柏。', en: 'Sixty li east is Mount Pi, with much chalk and ochre, and pines and cypresses.' },
    { type: 'para', zh: '又东六十里，曰瑶碧之山，其木多梓枏，其阴多青雘，其阳多白金。有鸟焉，其状如雉，恒食蜚，名曰鸩。', en: 'Sixty li east is Mount Yaobi, with catalpa and nanmu trees, azurite on its north face and white gold on its south. A bird called the zhen, shaped like a pheasant and constantly eating insects, is the poisonous zhen bird.' },
    { type: 'para', zh: '又东四十里，曰支离之山。济水出焉，南流注于汉。有鸟焉，其名曰婴勺，其状如鹊，赤目、赤喙、白身，其尾若勺，其鸣自呼。多㸲牛，多羬羊。', en: 'Forty li east is Mount Zhili. The Ji River flows south into the Han River. A bird called the yingshao, shaped like a magpie with red eyes, red beak, white body and a spoon-shaped tail, has a cry like its name. There are many zong cattle and qian sheep.' },
    { type: 'para', zh: '又东北五十里，曰祑𥮐之山，其上多松柏机桓。', en: 'Fifty li northeast is Mount Zhiye, with pines, cypresses, ji and huan trees above.' },
    { type: 'para', zh: '又西北一百里，曰堇理之山，其上多松柏，多美梓；其阴多丹雘，多金；其兽多豹虎。有鸟焉，其状如鹊，青身白喙，白目白尾，名曰青耕，可以御疫，其鸣自叫。', en: 'One hundred li northwest is Mount Jinli, with pines and cypresses, fine catalpa, azurite and gold on its north face, and tigers and leopards as beasts. A bird called the qinggeng, shaped like a magpie with blue body, white beak, white eyes and white tail, wards off epidemics—its cry is like its name.' },
    { type: 'para', zh: '又东南三十里，曰依軲之山，其上多杻橿，多苴。有兽焉，其状如犬，虎爪有甲，其名曰獜，善駚𤘝，食者不风。', en: 'Thirty li southeast is Mount Yigu, with oak and zhen trees and much zhu. A beast called the lin, shaped like a dog with tiger claws and armor, is good at galloping—eating it prevents wind disorders.' },
    { type: 'para', zh: '又东南三十五里，曰即谷之山，多美玉，多玄豹，多闾麈，多麢㚟。其阳多珉，其阴多青雘。', en: 'Thirty-five li southeast is Mount Jigu, with much beautiful jade, black leopards, white deer and antelopes. There is silver on its south face and azurite on its north.' },
    { type: 'para', zh: '又东南四十里，曰鸡山，其上多美梓，多桑，其草多韭。', en: 'Forty li southeast is Mount Ji, with fine catalpa, mulberry and much chive grass.' },
    { type: 'para', zh: '又东南五十里，曰高前之山，其上有水焉，甚寒而清，帝台之浆也，饮之者不心痛。其上有金，其下有赭。', en: 'Fifty li southeast is Mount Gaoqian, with very cold, clear water above—the Emperor Tai\'s nectar; drinking it cures heart pain. There is gold above and ochre below.' },
    { type: 'para', zh: '又东南三十里，曰游戏之山，多杻橿榖，多玉，多封石。', en: 'Thirty li southeast is Mount Youxi, with oak, zhen and grain, much jade and feng stone.' },
    { type: 'para', zh: '又东南三十五里，曰从山，其上多松柏，其下多竹。从水出于其上，潜于其下，其中多三足鳖，枝尾，食之无蛊疾。', en: 'Thirty-five li southeast is Mount Cong, with pines and cypresses above and bamboo below. The Cong River flows above and below, containing many three-legged soft-shelled turtles with branched tails—eating them prevents poison.' },
    { type: 'para', zh: '又东南三十里，曰婴䃌之山，其上多松柏，其下多梓櫄。', en: 'Thirty li southeast is Mount Yingdun, with pines and cypresses above and catalpa and chun trees below.' },
    { type: 'para', zh: '又东南三十里，曰毕山。帝苑之水出焉，东北流注于视，其中多水玉，多蛟。其上多㻬琈之玉。', en: 'Thirty li east is Mount Bi. The Diyuan River flows northeast into the Shi waters, containing much water jade and many flood dragons. There is much turou jade above.' },
    { type: 'para', zh: '又东南二十里，曰乐马之山。有兽焉，其状如汇，赤如丹火，其名曰𤟑，见则其国大疫。', en: 'Twenty li southeast is Mount Lema. A beast called the zhi, shaped like a rabbit and red as cinnabar fire, foretells great plagues.' },
    { type: 'para', zh: '又东南二十五里，曰葴山，视水出焉，东南流注于汝水，其中多人鱼，多蛟，多颉。', en: 'Twenty-five li southeast is Mount Zhen. The Shi River flows southeast into the Ru waters, containing many human fish, flood dragons and xie.' },
    { type: 'para', zh: '又东四十里，曰婴山，其下多青雘，其上多金玉。', en: 'Forty li east is Mount Ying, with azurite below and gold and jade above.' },
    { type: 'para', zh: '又东三十里，曰虎首之山，多苴椆椐。', en: 'Thirty li east is Mount Hushou, with much zhu and chou zhen trees.' },
    { type: 'para', zh: '又东二十里，曰婴侯之山，其上多封石，其下多赤锡。', en: 'Twenty li east is Mount Yinghou, with feng stone above and red tin below.' },
    { type: 'para', zh: '又东五十里，曰大孰之山。杀水出焉，东北流注于视水，其中多白垩。', en: 'Fifty li east is Mount Dashu. The Sha River flows northeast into the Shi waters, containing much white chalk.' },
    { type: 'para', zh: '又东四十里，曰卑山，其上多桃李苴梓，多累。', en: 'Forty li east is Mount Bei, with peach, plum, zhu and catalpa trees and much lei.' },
    { type: 'para', zh: '又东三十里，曰倚帝之山，其上多玉，其下多金。有兽焉，状如鼣鼠，白耳白喙，名曰狙如，见则其国有大兵。', en: 'Thirty li east is Mount Yidi, with jade above and gold below. A beast called the juru, shaped like a mole rat with white ears and white beak, foretells great wars.' },
    { type: 'para', zh: '又东三十里，曰鲵山，鲵水出于其上，潜于其下，其中多美垩。其上多金，其下多青雘。', en: 'Thirty li east is Mount Ni. The Ni River flows above and below, containing much fine chalk. There is gold above and azurite below.' },
    { type: 'para', zh: '又东三十里，曰雅山。澧水出焉，东流注于视水，其中多大鱼。其上多美桑，其下多苴，多赤金。', en: 'Thirty li east is Mount Ya. The Li River flows east into the Shi waters, containing many large fish. There is much fine mulberry above, much zhu below and much red gold.' },
    { type: 'para', zh: '又东五十五里，曰宣山。沦水出焉，东南流注于视水，其中多蛟。其上有桑焉，大五十尺，其枝四衢，其叶大尺馀，赤理黄华青柎，名曰帝女之桑。', en: 'Fifty-five li east is Mount Xuan. The Lun River flows southeast into the Shi waters, containing many flood dragons. A mulberry tree above is fifty zhang tall, with four branches, leaves over a chi long, red grain, yellow flowers and green calyx—called the Emperor Daughter\'s Mulberry.' },
    { type: 'para', zh: '又东四十五里，曰衡山，其上多青雘，多桑，其鸟多鸜鹆。', en: 'Forty-five li east is Mount Heng, with much azurite, mulberry and many myna birds.' },
    { type: 'para', zh: '又东四十里，曰丰山，其上多封石，其木多桑，多羊桃，状如桃而方茎，可以为皮张。', en: 'Forty li east is Mount Feng, with much feng stone, mulberry and yangtao trees—peach-like with square stems, usable for leather stretching.' },
    { type: 'para', zh: '又东七十里，曰妪山，其上多美玉，其下多金，其草多鸡谷。', en: 'Seventy li east is Mount Yu, with much fine jade above, gold below, and much chicken-grain grass.' },
    { type: 'para', zh: '又东三十里，曰鲜山，其木多楢杻苴，其草多虋冬，其阳多金，其阴多铁。有兽焉，其状如膜犬，赤喙、赤目、白尾，见则其邑有火，名曰𤝻即。', en: 'Thirty li east is Mount Xian, with yu, oak and zhu trees, much men dong grass, gold on its south face and iron on its north. A beast called the feiji, shaped like a membrane dog with red beak, red eyes and white tail, foretells fire in that city.' },
    { type: 'para', zh: '又东三十里，曰章山，其阳多金，其阴多美石。皋水出焉，东流注于丰水，其中多脃石。', en: 'Thirty li east is Mount Zhang, with gold on its south face and beautiful stones on its north. The Gao River flows east into the Feng waters, containing much brittle stone.' },
    { type: 'para', zh: '又东二十五里，曰大支之山，其阳多金，其木多榖柞，无草木。', en: 'Twenty-five li east is Mount Dazhi, with gold on its south face and paper mulberry and oaks but no plants.' },
    { type: 'para', zh: '又东五十里，曰区吴之山，其木多苴。', en: 'Fifty li east is Mount Quwu, with much zhu trees.' },
    { type: 'para', zh: '又东五十里，曰声匈之山，其木多榖，多玉，上多封石。', en: 'Fifty li east is Mount Shengxiong, with much grain, jade and feng stone above.' },
    { type: 'para', zh: '又东五十里，曰大騩之山，其阳多赤金，其阴多砥石。', en: 'Fifty li east is Mount Dagui, with red copper on its south face and whetstones on its north.' },
    { type: 'para', zh: '又东十里，曰踵臼之山，无草木。', en: 'Ten li east is Mount Zhongjiu, with no plants.' },
    { type: 'para', zh: '又东北七十里，曰历石之山，其木多荆棘，其阳多黄金，其阴多砥石。有兽焉，其状如狸而白首虎爪，名曰梁渠，见则其国有大兵。', en: 'Seventy li northeast is Mount Lishi, with thorns and brambles, gold on its south face and whetstones on its north. A beast called the liangqu, shaped like a badger with a white head and tiger claws, foretells great wars.' },
    { type: 'para', zh: '又东南一百里，曰求山。求水出于其上，潜于其下，中有美赭。其木多苴，多䉋。其阳多金，其阴多铁。', en: 'One hundred li southeast is Mount Qiu. The Qiu River flows above and below, containing much fine ochre. There is much zhu and qian, gold on its south face and iron on its north.' },
    { type: 'para', zh: '又东二百里，曰丑阳之山，其上多椆椐。有鸟焉，其状如乌而赤足，名曰䳅鵌，可以御火。', en: 'Two hundred li east is Mount Chouyang, with chou zhen trees. A bird called the zhitu, shaped like a crow with red feet, wards off fire.' },
    { type: 'para', zh: '又东三百里，曰奥山，其上多柏杻橿，其阳多㻬琈之玉。奥水出焉，东流注于视水。', en: 'Three hundred li east is Mount Ao, with cypresses, oak and zhen trees, and turou jade on its south face. The Ao River flows east into the Shi waters.' },
    { type: 'para', zh: '又东三十五里，曰服山，其木多苴，其上多封石，其下多赤锡。', en: 'Thirty-five li east is Mount Fu, with much zhu, feng stone above and red tin below.' },
    { type: 'para', zh: '又东百十里，曰杳山，其上多嘉荣草，多金玉。', en: 'One hundred ten li east is Mount Yao, with much jiarong grass and gold and jade.' },
    { type: 'para', zh: '又东三百五十里，曰几山，其木多楢檀杻，其草多香。有兽焉，其状如彘，黄身、白头、白尾，名曰闻𧲂，见则天下大风。', en: 'Three hundred fifty li east is Mount Ji, with yu, sandalwood and oak trees and much fragrant grass. A beast called the wenlang, shaped like a pig with yellow body, white head and white tail, brings great winds under heaven.' },
    { type: 'para', zh: '凡荆山之首，自翼望之山至于几山，凡四十八山，三千七百三十二里。其神状皆豕身人首。其祠：毛用一雄鸡祈，瘗用一珪，糈用五种之精。禾山，帝也，其祠：太牢之具，羞瘗倒毛；用一璧，牛无常。堵山、玉山，冢也，皆倒祠，羞毛少牢，婴毛吉玉。', en: 'In all, the Jing Mountains from Mount Yiwang to Mount Ji comprise forty-eight peaks spanning 3,732 li. Their spirits all have pig bodies and human heads. For the sacrifice: one rooster is used for prayer, one gui is buried, with five types of refined grain. He Mountain is the emperor—its sacrifice uses the full set of livestock, offerings buried with reversed fur, with one bi and cattle not fixed. Du Mountain and Yu Mountain are tombs—both with reversed sacrifices, offerings with the full set of livestock, with infant fur and auspicious jade.' },
    { type: 'heading', zh: '中次十二经', en: 'Central Mountains XII' },
    { type: 'para', zh: '《中次十二经》洞庭山之首，曰篇遇之山，无草木，多黄金。', en: 'The twelfth Central Mountains, the Dongting Mountains, begin at Mount Pianyu, with no plants and much gold.' },
    { type: 'para', zh: '又东南五十里，曰云山，无草木。有桂竹，甚毒，伤人必死。其上多黄金，其下多㻬琈之玉。', en: 'Fifty li southeast is Mount Yun, with no plants. There is a cassia bamboo so toxic that anyone wounded by it dies. There is much gold above and turou jade below.' },
    { type: 'para', zh: '又东南一百三十里，曰龟山，其木多榖柞椆椐，其上多黄金，其下多青雄黄，多扶竹。', en: 'One hundred thirty li southeast is Mount Gui, with paper mulberry, oak and chou zhen trees, gold above, blue realgar below and much fu bamboo.' },
    { type: 'para', zh: '又东七十里，曰丙山，多筀竹，多黄金铜铁，无木。', en: 'Seventy li east is Mount Bing, with much gui bamboo, gold, copper and iron, and no trees.' },
    { type: 'para', zh: '又东南五十里，曰风伯之山，其上多金玉，其下多痠石、文石，多铁，其木多柳杻檀楮。其东有林焉，名曰莽浮之林，多美木鸟兽。', en: 'Fifty li southeast is Mount Fengbo, with gold and jade above, suan stone and patterned stone below, much iron, willow, oak, sandalwood and paper mulberry trees. A forest called Mangfu lies to its east, with much beautiful trees, birds and beasts.' },
    { type: 'para', zh: '又东一百五十里，曰夫夫之山，其上多黄金，其下多青雄黄，其木多桑楮，其草多竹、鸡鼓。神于儿居之，其状人身而身操两蛇，常游于江渊，出入有光。', en: 'One hundred fifty li east is Mount Fufu, with gold above, blue realgar below, mulberry and paper mulberry trees, and much bamboo and jigu grass. The deity Yu\'er dwells here—human-bodied, holding two snakes, constantly swimming in the Yangtze depths, emerging and entering with light.' },
    { type: 'para', zh: '又东南一百二十里，曰洞庭之山。其上多黄金，其下多银铁，其木多柤棃橘櫾，其草多葌、蘼芜、芍药、芎藭。帝之二女居之，是常游于江渊。澧沅之风，交潇湘之渊，是在九江之闲，出入必以飘风暴雨。是多怪神，状如人而载蛇，左右手操蛇。多怪鸟。', en: 'One hundred twenty li southeast is Mount Dongting, with gold above, silver and iron below, jujube, pear, orange and pomelo trees, and jian, miliao, peony and chuanxiong grass. The Emperor\'s two daughters dwell here, constantly swimming in the Yangtze depths. The winds of Li and Yuan meet in the depths of Xiao and Xiang—this lies between the nine rivers, emerging and entering with violent wind and rain. There are many strange gods shaped like humans carrying snakes, holding snakes in both hands, and many strange birds.' },
    { type: 'para', zh: '又东南一百八十里，曰暴山。其木多棕枏荆棘竹箭䉋箘，其是多黄金玉，其下多文石铁，其兽多麋鹿𪊨就。', en: 'One hundred eighty li southeast is Mount Bao, with palm, nanmu, thorns, bamboo arrows and jun bamboo, much gold and jade above, patterned stone and iron below, and elk, deer and jiujiu as beasts.' },
    { type: 'para', zh: '又东南二百里，曰即公之山，其上多黄金，其下多㻬琈之玉，其木多柳杻檀桑。有兽焉，其状如龟，而白身赤首，名曰蛫，是可以御火。', en: 'Two hundred li southeast is Mount Jigong, with gold above, turou jade below, willow, oak, sandalwood and mulberry trees. A beast called the gui, shaped like a turtle with a white body and red head, wards off fire.' },
    { type: 'para', zh: '又东南一百五十九里，有尧山，其阴多黄垩，其阳多黄金，其木多荆棘柳檀，其草多藷藇𦬸。', en: 'One hundred fifty-nine li southeast is Mount Yao, with yellow chalk on its north face, gold on its south, thorns, brambles, willow and sandalwood trees, and much shuyu and xuan grass.' },
    { type: 'para', zh: '又东南一百里，曰江浮之山，其上多银砥砺，无草木，其兽多豕鹿。', en: 'One hundred li southeast is Mount Jiangfu, with silver and whetstones above, no plants, and pigs and deer as beasts.' },
    { type: 'para', zh: '又东二百里，曰真陵之山，其上多黄金，其下多玉，其木多榖柞柳杻，其草多荣草。', en: 'Two hundred li east is Mount Zhenling, with gold above, jade below, paper mulberry, oak, willow and oak trees, and much rong grass.' },
    { type: 'para', zh: '又东南一百二十里，曰阳帝之山，多美铜，其木多橿杻檿楮，其兽多麢麝。', en: 'One hundred twenty li southeast is Mount Yangdi, with much fine copper, zhen, oak, yang and paper mulberry trees, and antelopes and musk deer as beasts.' },
    { type: 'para', zh: '又南九十里，曰柴桑之山，其上多银，其下多碧，多泠石、赭，其木多柳𦬊楮桑，其兽多麋鹿，多白蛇飞蛇。', en: 'Ninety li south is Mount Chaisang, with silver above, jasper below, much cold stone and ochre, willow, jing, paper mulberry and mulberry trees, elk and deer as beasts, and many white and flying snakes.' },
    { type: 'para', zh: '又东二百三十里，曰荣余之山，其上多铜；其下多银，其木多柳𦬊，其虫多怪蛇怪虫。', en: 'Two hundred thirty li east is Mount Rongyu, with copper above, silver below, willow and jing trees, and many strange snakes and insects.' },
    { type: 'para', zh: '凡洞庭山之首，自篇遇之山至于荣余之山，凡十万山，二千八百里。其神状皆鸟身而龙首。其祠：毛用一雄鸡、一牝豚刏，糈用稌。凡夫夫之山、即公之山、尧山、阳帝之山皆冢也，其祠：皆肆瘗，祈用酒，毛用少牢，婴毛一吉玉。洞庭、荣余山神也，其祠：皆肆瘗，祈酒太牢祠，婴用圭璧十五，五彩惠之。', en: 'In all, the Dongting Mountains from Mount Pianyu to Mount Rongyu comprise ten peaks spanning 2,800 li. Their spirits all have bird bodies and dragon heads. For the sacrifice: one rooster and one sow are used, with millet for grain. Fufu, Jigong, Yao and Yangdi are all tombs—their sacrifices are all buried, with wine for prayer, the full set of livestock for fur, and one auspicious jade for the infant. Dongting and Rongyu are mountain gods—their sacrifices are all buried, with wine and the full set of livestock, and fifteen gui and bi for the infant, adorned with five colors.' },
    { type: 'para', zh: '右中经之山，大凡百九十七山，二万一千三百七十一里。', en: 'Thus the record of the Central Mountains: one hundred ninety-seven mountains in all, spanning 21,371 li.' },
    { type: 'para', zh: '大凡天下名山五千三百七十，居地，大凡六万四千五十六里。', en: 'In all, the famous mountains under heaven number five thousand three hundred seventy, spanning sixty-four thousand fifty-six li of inhabited land.' },
    { type: 'heading', zh: '五臧山经', en: 'The Five Treasures Mountain Classic' },
    { type: 'para', zh: '禹曰：天下名山，经五千三百七十山，六万四千五十六里，居地也。言其《五臧》，盖其馀小山甚众，不足记云。天地之东西二万八千里，南北二万六千里，出水之山者八千里，受水者八千里，出铜之山四百六十七，出铁之山三千六百九十。此天地之所分壤树穀也，戈矛之所发也，刀鎩之所起也，能者有馀，拙者不足。封于太山，禅于梁父，七十二家，得失之数，皆在此内，是谓国用。', en: 'Yu said: The world\'s famous mountains number five thousand three hundred seventy, spanning sixty-four thousand fifty-six li of inhabited land. These are the Five Treasures—the remaining small mountains are too numerous to record. The world spans twenty-eight thousand li east to west and twenty-six thousand li north to south. Mountains from which water flows span eight thousand li; those receiving water span eight thousand li. Copper-producing mountains number four hundred sixty-seven; iron-producing mountains number three thousand six hundred ninety. These are where heaven and earth divide the soil and plant grain, where spears and halberds originate, where swords and blades arise—the capable have abundance, the clumsy have deficiency. Enfeoffed at Mount Tai and sacrificing at Liangfu, seventy-two families—the numbers of gain and loss all lie within this; these are called the state\'s resources.' },
    { type: 'para', zh: '右《五臧山经》五篇，大凡一万五千五百三字。', en: 'Thus the Five Treasures Mountain Classic comprises five chapters, totaling fifteen thousand five hundred three characters.' },
]

